UPDATE `creature` SET `MovementType`=2, `spawndist`=0, `currentwaypoint`=0 WHERE `guid` IN (47644, 47910, 324573, 324595, 324601, 324620, 324648, 324651, 324654, 324671, 324741, 324753, 324755, 324756, 324757, 324760, 324761, 324763, 324764, 324771, 324789, 324790, 324803, 324809, 324811, 324822, 324841, 324866, 324877, 324899, 324900, 324902, 324960, 324966, 324973, 324981, 324985, 327471);
